diff --git a/src/pipeline-self-audit.test.js b/src/pipeline-self-audit.test.js
index 1389be9c..dfbfeeef 100644
--- a/src/pipeline-self-audit.test.js
+++ b/src/pipeline-self-audit.test.js
@@ -97,3 +97,23 @@ test('buildAuditTask produces a task on the given domain with the evidence embed
   assert.equal(task.promptContext.signature, 'project_search::fabricated-ungrounded-claim');
   assert.equal(task.promptContext.taskCount, CLUSTER_THRESHOLD);
 });
+
+test('buildAuditRawText labels gate-inconclusive clusters distinctly when any task has reviewInconclusive === true', () => {
+  const tasks = Array.from({ length: CLUSTER_THRESHOLD }, (_, i) => {
+    const t = makeBlocked(`t${i}`, 'arch_import', 'Ornith review inconclusive, no confident majority');
+    if (i === 0) t.reviewInconclusive = true;
+    return t;
+  });
+  const text = buildAuditRawText({ signature: 'arch_import::inconclusive-review', tasks });
+  assert.match(text, /gate-inconclusive \(stochastic re-roll, not a genuine reviewer rejection\)/);
+});
+
+test('buildAuditRawText still renders the original faultSideNote when no task has reviewInconclusive', () => {
+  const tasks = Array.from({ length: CLUSTER_THRESHOLD }, (_, i) =>
+    makeBlocked(`t${i}`, 'arch_import', 'the draft contains no implementation'));
+  const text = buildAuditRawText({ signature: 'arch_import::empty-degenerate-draft', tasks });
+  // Should NOT contain the gate-inconclusive label
+  assert.doesNotMatch(text, /gate-inconclusive \(stochastic re-roll, not a genuine reviewer rejection\)/);
+  // Should still contain the original faultSide classification (model-side for empty-degenerate-draft)
+  assert.match(text, /Classified as:/);
+});

